(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const texts = {};
  const grab = (k) => { texts[k] = document.body.innerText || ''; };
  const btn = (scope, word) => [...document.querySelectorAll(scope)].find((b) => (b.textContent || '').includes(word));

  await sleep(500);
  grab('作品列表');

  document.querySelector('.tb-project-main')?.click();
  await sleep(3200);
  grab('作品详情');

  btn('.pj-head-actions button', '分享作品')?.click();
  await sleep(1500);
  grab('分享弹层');
  document.querySelector('.sw-close')?.click();
  await sleep(400);

  btn('.pj-head-actions button', 'AI 识别元件')?.click();
  await sleep(1000);
  grab('识别弹层');
  document.querySelector('.lr-close')?.click();
  await sleep(400);

  document.querySelector('.pj-crumb-link')?.click();
  await sleep(1800);

  btn('.tb-actions button', '识别设置')?.click();
  await sleep(1200);
  grab('识别设置');
  document.querySelector('.ai-close')?.click();
  await sleep(500);

  btn('.tb-actions button', '备份与恢复')?.click();
  await sleep(1200);
  grab('备份弹层');
  document.querySelector('.bk-close')?.click();
  await sleep(500);

  btn('.tb-actions button', '新建项目')?.click();
  await sleep(800);
  grab('新建项目');

  const banned = ['API Key', 'API key', 'apikey', 'ApiKey', '密钥', 'JSON', 'json', '导入', '导出', '项目包', 'token', 'Token', '令牌', 'Key'];
  const hits = {};
  const lines = [];
  for (const [k, v] of Object.entries(texts)) {
    for (const b of banned) {
      if (v.includes(b)) (hits[k] = hits[k] || []).push(b);
    }
    for (const line of v.split('\n')) {
      const t = line.trim();
      if (!t) continue;
      for (const b of banned) if (t.includes(b)) lines.push(k + ' | ' + b + ' | ' + t.slice(0, 70));
    }
  }
  return JSON.stringify({ views: Object.keys(texts), hits, sample: [...new Set(lines)].slice(0, 30), detailHasTip: (texts['作品详情'] || '').includes('分享作品') });
})()
